function rollSeasonIfDue(){const now=Date.now(),duration=30*86400000;if(!state.seasonStartedAt)state.seasonStartedAt=now;const elapsed=now-state.seasonStartedAt;if(elapsed<duration)return false;const cycles=Math.floor(elapsed/duration),profileRewards=[...(Array.isArray(state.profileRewards)?state.profileRewards:[])],archive=[...(Array.isArray(state.seasonArchive)?state.seasonArchive:[])];for(let n=0;n<cycles;n++){const season=(state.seasonNumber||1)+n,completedAt=state.seasonStartedAt+(n+1)*duration,bossWon=state.bossDefeated===true;archive.push({season,completedAt,found:(state.found||[]).length,missions:(state.missions||[]).length,gpuLevel:state.gpuLevel||1,bossDefeated:bossWon,reward:bossWon?'Трофей «Нульовий охоронець»':'Сезон завершено'});if(bossWon&&!profileRewards.includes('season-boss-'+season))profileRewards.push('season-boss-'+season)}state={...defaults,seasonStartedAt:state.seasonStartedAt+cycles*duration,seasonNumber:(state.seasonNumber||1)+cycles,dailyClaimDate:state.dailyClaimDate||'',dailyClaimAt:state.dailyClaimAt||0,dailyRewardIndex:state.dailyRewardIndex||0,dailyStreak:state.dailyStreak||0,dailyMissionResetAt:state.dailyMissionResetAt||0,dailyMissionProgress:state.dailyMissionProgress||{explore:0,salvage:0,upgrade:0},dailyMissionClaims:state.dailyMissionClaims||[],profileRewards,seasonArchive:archive.slice(-20)};selected=zones[0];notice='Новий 12-денний сезон! Увесь сезонний прогрес оновлено, а постійні нагороди й трофеї збережені в профілі.';save();return true}
function newSalvageBoard(){const cells=Array(16).fill('');const indexes=[...Array(16).keys()];for(let i=indexes.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[indexes[i],indexes[j]]=[indexes[j],indexes[i]]}indexes.slice(0,4).forEach(i=>cells[i]='loot');indexes.slice(4,7).forEach(i=>cells[i]='trap');return cells}
function startSalvage(){state.salvageBoard=newSalvageBoard();state.salvagePicks=[];state.salvageResult='';state.salvageRewarded=false;state.salvageDone=false;notice='Польовий збір почався. Уникай пасток.';save();render()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{notice='Браузер не дозволив зберегти прогрес. Перевір налаштування сховища.';return false}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
